package lintsensitivity

import (
	"bytes"
	"fmt"
	"reflect"
	"strings"
	"testing"
)

var receiptBinding = strings.Repeat("c", 64)

// Independent wire examples, not generated by EncodeESLintReceipt.
func authoredReceipt(role Role, exit int, stdout, stderr []byte) []byte {
	header := fmt.Sprintf("CI-TRUST-ESLINT-RECEIPT/1\n%s\n%s\n%d\n%d\n%d\n", receiptBinding, role, exit, len(stdout), len(stderr))
	out := append([]byte(header), stdout...)
	return append(out, stderr...)
}

func TestESLintReceiptTriplet(t *testing.T) {
	var triplet []Observation
	for _, want := range observations(t) {
		tool := ESLintCapture{Status: Completed, ExitCode: want.ExitCode, Stdout: eslintJSON(want.Role == Fault)}
		before := bytes.Clone(tool.Stdout)
		wire, err := EncodeESLintReceipt(want.Role, receiptBinding, tool)
		authored := authoredReceipt(want.Role, want.ExitCode, tool.Stdout, nil)
		if err != nil || !bytes.Equal(wire, authored) || !bytes.Equal(tool.Stdout, before) {
			t.Fatalf("encoder mismatch: %v", err)
		}
		outer := ESLintCapture{Status: Completed, ExitCode: 0, Stdout: authored}
		got := DecodeESLintReceipt(want.Role, want.Identity, receiptBinding, outer)
		if !reflect.DeepEqual(got, want) || !bytes.Equal(authored, authoredReceipt(want.Role, want.ExitCode, tool.Stdout, nil)) {
			t.Fatalf("%+v", got)
		}
		triplet = append(triplet, got)
	}
	if Classify(triplet).Outcome != Sensitive {
		t.Fatal("authored triplet rejected")
	}
	triplet[1] = DecodeESLintReceipt(Fault, triplet[1].Identity, receiptBinding, ESLintCapture{Status: Completed, Stdout: authoredReceipt(Fault, 0, eslintJSON(false), nil)})
	if Classify(triplet).Outcome != Insensitive {
		t.Fatal("receipt made no-op sensitive")
	}
}

func TestESLintReceiptFailures(t *testing.T) {
	base := authoredReceipt(Fault, 1, eslintJSON(true), nil)
	id := observations(t)[0].Identity
	for name, bad := range map[string][]byte{
		"empty": nil, "truncated": base[:len(base)-1], "trailing": append(bytes.Clone(base), '\n'),
		"two receipts":      append(bytes.Clone(base), base...),
		"version":           bytes.Replace(base, []byte("RECEIPT/1"), []byte("RECEIPT/2"), 1),
		"binding":           bytes.Replace(base, []byte(receiptBinding), []byte(strings.Repeat("d", 64)), 1),
		"role":              bytes.Replace(base, []byte("\nFAULT\n"), []byte("\nCLEAN\n"), 1),
		"exit":              bytes.Replace(base, []byte("\n1\n"), []byte("\n2\n"), 1),
		"exit alias":        bytes.Replace(base, []byte("\n1\n"), []byte("\n01\n"), 1),
		"crlf":              bytes.Replace(base, []byte("RECEIPT/1\n"), []byte("RECEIPT/1\r\n"), 1),
		"oversized":         bytes.Repeat([]byte("x"), 65537),
		"invalid json":      authoredReceipt(Fault, 1, []byte("not-json"), nil),
		"tool stderr":       authoredReceipt(Fault, 1, eslintJSON(true), []byte("warning")),
		"inconsistent exit": authoredReceipt(Fault, 0, eslintJSON(true), nil),
	} {
		t.Run(name, func(t *testing.T) {
			got := DecodeESLintReceipt(Fault, id, receiptBinding, ESLintCapture{Status: Completed, Stdout: bad})
			if got.Status != InvalidOutput || len(got.Diagnostics) != 0 {
				t.Fatalf("accepted %s: %+v", name, got)
			}
		})
	}
	header := fmt.Sprintf("CI-TRUST-ESLINT-RECEIPT/1\n%s\nFAULT\n1\n", receiptBinding)
	for _, length := range []string{"", "-1", "+1", "01", "1.0", "1e2", " 1", "65537", "9999999999999999999999"} {
		bad := []byte(header + length + "\n0\nx")
		if got := DecodeESLintReceipt(Fault, id, receiptBinding, ESLintCapture{Status: Completed, Stdout: bad}); got.Status != InvalidOutput {
			t.Fatalf("accepted length %q", length)
		}
	}
	for _, outer := range []ESLintCapture{
		{Status: Completed, ExitCode: 1, Stdout: base},
		{Status: Completed, ExitCode: -1, Stdout: base},
		{Status: Completed, Stdout: base, Stderr: []byte("transport warning")},
	} {
		if DecodeESLintReceipt(Fault, id, receiptBinding, outer).Status != InvalidOutput {
			t.Fatal("receipt hid outer failure")
		}
	}
	for _, status := range []Status{Denied, Unavailable, TimedOut, Crashed, CleanupUnverified, InvalidOutput, "UNKNOWN"} {
		want := status
		if status == "UNKNOWN" {
			want = InvalidOutput
		}
		got := DecodeESLintReceipt(Fault, id, receiptBinding, ESLintCapture{Status: status, Stdout: base})
		if got.Status != want || len(got.Diagnostics) != 0 {
			t.Fatalf("lost outer status %s: %+v", status, got)
		}
	}
	for _, binding := range []string{"", strings.Repeat("C", 64), strings.Repeat("c", 63)} {
		if DecodeESLintReceipt(Fault, id, binding, ESLintCapture{Status: Completed, Stdout: base}).Status != InvalidOutput {
			t.Fatal("invalid expected binding accepted")
		}
	}
}

func TestESLintReceiptBounds(t *testing.T) {
	id := observations(t)[0].Identity
	base := eslintJSON(false)
	// At this boundary the canonical stdout length has five digits.
	header := fmt.Sprintf("CI-TRUST-ESLINT-RECEIPT/1\n%s\nCLEAN\n0\n65536\n0\n", receiptBinding)
	payload := append(bytes.Clone(base), bytes.Repeat([]byte(" "), MaxESLintReceiptBytes-len(header)-len(base))...)
	wire := authoredReceipt(Clean, 0, payload, nil)
	if len(wire) != MaxESLintReceiptBytes || DecodeESLintReceipt(Clean, id, receiptBinding, ESLintCapture{Status: Completed, Stdout: wire}).Status != Completed {
		t.Fatal("exact wire bound rejected")
	}
	capture := ESLintCapture{Status: Completed, Stdout: payload}
	encoded, err := EncodeESLintReceipt(Clean, receiptBinding, capture)
	if err != nil || !bytes.Equal(encoded, wire) {
		t.Fatal("encoder exact bound rejected")
	}
	encoded[len(encoded)-1] = 'x'
	if payload[len(payload)-1] != ' ' {
		t.Fatal("encoder aliases input")
	}
	capture.Stdout = append(bytes.Clone(payload), ' ')
	if b, err := EncodeESLintReceipt(Clean, receiptBinding, capture); err == nil || b != nil {
		t.Fatal("wire overflow accepted")
	}
	for _, capture := range []ESLintCapture{
		{Status: Denied}, {Status: Completed, ExitCode: 2},
		{Status: Completed, Stdout: bytes.Repeat([]byte("x"), 65537)},
		{Status: Completed, Stderr: bytes.Repeat([]byte("x"), 65537)},
	} {
		if b, err := EncodeESLintReceipt(Clean, receiptBinding, capture); err == nil || b != nil {
			t.Fatal("invalid producer capture accepted")
		}
	}
	if _, err := EncodeESLintReceipt("OTHER", receiptBinding, ESLintCapture{Status: Completed}); err == nil {
		t.Fatal("unknown producer role accepted")
	}
	if _, err := EncodeESLintReceipt(Clean, "bad", ESLintCapture{Status: Completed}); err == nil {
		t.Fatal("invalid producer binding accepted")
	}
}

func FuzzESLintReceipt(f *testing.F) {
	f.Add(authoredReceipt(Fault, 1, eslintJSON(true), nil))
	f.Add([]byte("CI-TRUST-ESLINT-RECEIPT/1\n"))
	f.Fuzz(func(t *testing.T, b []byte) {
		before := bytes.Clone(b)
		got := DecodeESLintReceipt(Fault, observations(t)[0].Identity, receiptBinding, ESLintCapture{Status: Completed, Stdout: b})
		if !bytes.Equal(before, b) {
			t.Fatal("receipt input mutated")
		}
		if got.Status != Completed && len(got.Diagnostics) != 0 {
			t.Fatal("failed receipt retained diagnostics")
		}
	})
}
